    @SuppressWarnings("unchecked")
    private <E> DetCics.Store<E> store(String name) {
        return (DetCics.Store<E>) stores.computeIfAbsent(name, n -> switch (n) {
            case "ACCTDAT" -> new DetCics.Store<AccountRecord>(accountRecordRepository::findAll, e -> e.toRecord(CS), b -> AccountRecord.fromRecord(b, CS), accountRecordRepository::save, accountRecordRepository::delete, 0, 11, CS).withFindById(rec -> accountRecordRepository.findById(id_AccountRecord(rec)));
            case "CXACAIX" -> new DetCics.Store<CardXrefRecord>(cardXrefRecordRepository::findAll, e -> e.toRecord(CS), b -> CardXrefRecord.fromRecord(b, CS), cardXrefRecordRepository::save, cardXrefRecordRepository::delete, 25, 11, CS);
            case "CUSTDAT" -> new DetCics.Store<CustomerRecord>(customerRecordRepository::findAll, e -> e.toRecord(CS), b -> CustomerRecord.fromRecord(b, CS), customerRecordRepository::save, customerRecordRepository::delete, 0, 9, CS).withFindById(rec -> customerRecordRepository.findById(id_CustomerRecord(rec)));
            default -> throw new Hole("CICS file " + n + ": no store in the generated project");
        });
    }

