    /**
     * 0000-MAIN: entry paragraph of the account-update program.
     * Resets working storage, restores (or initialises) the COMMAREA, validates the
     * PF key, and then either returns to the calling program (PF3), re-sends a blank
     * screen, or processes inputs, decides the action and sends the map.
     */
    private int p0() {
        // EXEC CICS HANDLE ABEND LABEL(ABEND-ROUTINE) END-EXEC
        task.handleAbend("ABEND-ROUTINE");
        // INITIALIZE CC-WORK-AREA WS-MISC-STORAGE WS-COMMAREA
        initCcWorkArea();
        initWsMiscStorage();
        Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(f1297_WS_COMMAREA.storage(), f1297_WS_COMMAREA.offset() + 0, 2000, false), CS);
        // MOVE LIT-THISTRANID TO WS-TRANID
        Cobol.move(f215_LIT_THISTRANID, f5_WS_TRANID, CS);
        // SET WS-RETURN-MSG-OFF TO TRUE
        Cobol.moveFigurative(Figurative.SPACES, f212_WS_RETURN_MSG, CS);
        // IF EIBCALEN IS EQUAL TO 0 OR (CDEMO-FROM-PROGRAM = LIT-MENUPGM AND NOT CDEMO-PGM-REENTER)
        if (Cobol.num(f1308_EIBCALEN, CS).compareTo(D0) == 0 || isFromMenuAndNotReenter()) {
            // INITIALIZE CARDDEMO-COMMAREA WS-THIS-PROGCOMMAREA
            initCardDemoCommarea();
            initThisProgCommarea();
            // SET CDEMO-PGM-ENTER TO TRUE
            Cobol.move(D0, f1131_CDEMO_PGM_CONTEXT, CS);
            // SET ACUP-DETAILS-NOT-FETCHED TO TRUE
            Cobol.moveFigurative(Figurative.LOW_VALUES, f1147_ACUP_CHANGE_ACTION, CS);
        } else {
            // MOVE DFHCOMMAREA (1:LENGTH OF CARDDEMO-COMMAREA) TO CARDDEMO-COMMAREA
            Cobol.move(f1298_DFHCOMMAREA.ref(1, Integer.valueOf(BigDecimal.valueOf(160).intValue())), f1123_CARDDEMO_COMMAREA, CS);
            // MOVE DFHCOMMAREA(LENGTH OF CARDDEMO-COMMAREA + 1: LENGTH OF WS-THIS-PROGCOMMAREA ) TO WS-THIS-PROGCOMMAREA
            Cobol.move(f1298_DFHCOMMAREA.ref(BigDecimal.valueOf(160).add(D1).intValue(), Integer.valueOf(BigDecimal.valueOf(873).intValue())), f1145_WS_THIS_PROGCOMMAREA, CS);
        }
        // PERFORM YYYY-STORE-PFKEY THRU YYYY-STORE-PFKEY-EXIT
        perform(83, 84);
        // SET PFK-INVALID TO TRUE
        Cobol.move("1", f91_WS_PFK_FLAG, CS);
        // IF CCARD-AID-ENTER OR CCARD-AID-PFK03 OR (CCARD-AID-PFK05 AND ACUP-CHANGES-OK-NOT-CONFIRMED) OR (CCARD-AID-PFK12 AND NOT ACUP-DETAILS-NOT-FETCHED)
        if (isAid("ENTER")
                || isAid("PFK03")
                || (isAid("PFK05") && Cobol.compare(f1147_ACUP_CHANGE_ACTION, "N", CS) == 0)
                || (isAid("PFK12") && !isLowValuesOrSpaces(f1147_ACUP_CHANGE_ACTION))) {
            // SET PFK-VALID TO TRUE
            Cobol.move("0", f91_WS_PFK_FLAG, CS);
        }
        // IF PFK-INVALID
        if (Cobol.compare(f91_WS_PFK_FLAG, "1", CS) == 0) {
            // SET CCARD-AID-ENTER TO TRUE
            Cobol.move("ENTER", f246_CCARD_AID, CS);
        }
        // EVALUATE TRUE
        if (isAid("PFK03")) {
            // SET CCARD-AID-PFK03 TO TRUE
            Cobol.move("PFK03", f246_CCARD_AID, CS);
            // IF CDEMO-FROM-TRANID EQUAL LOW-VALUES OR CDEMO-FROM-TRANID EQUAL SPACES
            if (isLowValuesOrSpaces(f1125_CDEMO_FROM_TRANID)) {
                // MOVE LIT-MENUTRANID TO CDEMO-TO-TRANID
                Cobol.move(f227_LIT_MENUTRANID, f1127_CDEMO_TO_TRANID, CS);
            } else {
                // MOVE CDEMO-FROM-TRANID TO CDEMO-TO-TRANID
                Cobol.move(f1125_CDEMO_FROM_TRANID, f1127_CDEMO_TO_TRANID, CS);
            }
            // IF CDEMO-FROM-PROGRAM EQUAL LOW-VALUES OR CDEMO-FROM-PROGRAM EQUAL SPACES
            if (isLowValuesOrSpaces(f1126_CDEMO_FROM_PROGRAM)) {
                // MOVE LIT-MENUPGM TO CDEMO-TO-PROGRAM
                Cobol.move(f226_LIT_MENUPGM, f1128_CDEMO_TO_PROGRAM, CS);
            } else {
                // MOVE CDEMO-FROM-PROGRAM TO CDEMO-TO-PROGRAM
                Cobol.move(f1126_CDEMO_FROM_PROGRAM, f1128_CDEMO_TO_PROGRAM, CS);
            }
            // MOVE LIT-THISTRANID TO CDEMO-FROM-TRANID
            Cobol.move(f215_LIT_THISTRANID, f1125_CDEMO_FROM_TRANID, CS);
            // MOVE LIT-THISPGM TO CDEMO-FROM-PROGRAM
            Cobol.move(f214_LIT_THISPGM, f1126_CDEMO_FROM_PROGRAM, CS);
            // SET CDEMO-USRTYP-USER TO TRUE
            Cobol.move("U", f1130_CDEMO_USER_TYPE, CS);
            // SET CDEMO-PGM-ENTER TO TRUE
            Cobol.move(D0, f1131_CDEMO_PGM_CONTEXT, CS);
            // MOVE LIT-THISMAPSET TO CDEMO-LAST-MAPSET
            Cobol.move(f216_LIT_THISMAPSET, f1144_CDEMO_LAST_MAPSET, CS);
            // MOVE LIT-THISMAP TO CDEMO-LAST-MAP
            Cobol.move(f217_LIT_THISMAP, f1143_CDEMO_LAST_MAP, CS);
            // EXEC CICS SYNCPOINT END-EXEC
            task.syncpoint();
            // EXEC CICS XCTL PROGRAM (CDEMO-TO-PROGRAM) COMMAREA(CARDDEMO-COMMAREA) END-EXEC
            String xr1 = task.xctl(Cobol.text(f1128_CDEMO_TO_PROGRAM, CS).strip(), out_CarddemoCommarea(f1123_CARDDEMO_COMMAREA.storage(), f1123_CARDDEMO_COMMAREA.offset()));
            if ("NORMAL".equals(xr1)) throw new Goback();
            Cobol.store(f1329_EIBRESP, BigDecimal.valueOf(DetCics.resp(xr1)), false, CS);
            Cobol.store(f1330_EIBRESP2, BigDecimal.valueOf(0), false, CS);
            if (DetCics.resp(xr1) != 0) {
                int to = condition(DetCics.condition(DetCics.resp(xr1)));
                if (to >= 0) return GOTO | to;
            }
        } else if ((isLowValuesOrSpaces(f1147_ACUP_CHANGE_ACTION) && Cobol.compare(f1131_CDEMO_PGM_CONTEXT, D0, CS) == 0)
                || isFromMenuAndNotReenter()) {
            // INITIALIZE WS-THIS-PROGCOMMAREA
            initThisProgCommarea();
            // PERFORM 3000-SEND-MAP THRU 3000-SEND-MAP-EXIT
            perform(45, 46);
            // SET CDEMO-PGM-REENTER TO TRUE
            Cobol.move(D1, f1131_CDEMO_PGM_CONTEXT, CS);
            // SET ACUP-DETAILS-NOT-FETCHED TO TRUE
            Cobol.moveFigurative(Figurative.LOW_VALUES, f1147_ACUP_CHANGE_ACTION, CS);
            // GO TO COMMON-RETURN
            return GOTO | 1;
        } else if (Cobol.compare(f1147_ACUP_CHANGE_ACTION, "C", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "L", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "F", CS) == 0) {
            // INITIALIZE WS-THIS-PROGCOMMAREA WS-MISC-STORAGE CDEMO-ACCT-ID
            initThisProgCommarea();
            initWsMiscStorage();
            Cobol.moveFigurative(Figurative.ZEROS, Field.zoned(f1138_CDEMO_ACCT_ID.storage(), f1138_CDEMO_ACCT_ID.offset() + 0, 11, 0, false, false, false), CS);
            // SET CDEMO-PGM-ENTER TO TRUE
            Cobol.move(D0, f1131_CDEMO_PGM_CONTEXT, CS);
            // PERFORM 3000-SEND-MAP THRU 3000-SEND-MAP-EXIT
            perform(45, 46);
            // SET CDEMO-PGM-REENTER TO TRUE
            Cobol.move(D1, f1131_CDEMO_PGM_CONTEXT, CS);
            // SET ACUP-DETAILS-NOT-FETCHED TO TRUE
            Cobol.moveFigurative(Figurative.LOW_VALUES, f1147_ACUP_CHANGE_ACTION, CS);
            // GO TO COMMON-RETURN
            return GOTO | 1;
        } else {
            // PERFORM 1000-PROCESS-INPUTS THRU 1000-PROCESS-INPUTS-EXIT
            perform(3, 4);
            // PERFORM 2000-DECIDE-ACTION THRU 2000-DECIDE-ACTION-EXIT
            perform(43, 44);
            // PERFORM 3000-SEND-MAP THRU 3000-SEND-MAP-EXIT
            perform(45, 46);
            // GO TO COMMON-RETURN
            return GOTO | 1;
        }
        return 1;
    }

    /** CDEMO-FROM-PROGRAM = LIT-MENUPGM AND NOT CDEMO-PGM-REENTER */
    private boolean isFromMenuAndNotReenter() {
        return Cobol.compare(f1126_CDEMO_FROM_PROGRAM, f226_LIT_MENUPGM, CS) == 0
                && !(Cobol.compare(f1131_CDEMO_PGM_CONTEXT, D1, CS) == 0);
    }

    /** CCARD-AID is the given AID value (ENTER, PFK03, ...). */
    private boolean isAid(String aid) {
        return Cobol.compare(f246_CCARD_AID, aid, CS) == 0;
    }

    /** field EQUAL LOW-VALUES OR field EQUAL SPACES */
    private boolean isLowValuesOrSpaces(Field f) {
        return Cobol.compareFigurative(f, Figurative.LOW_VALUES, CS) == 0
                || Cobol.compareFigurative(f, Figurative.SPACES, CS) == 0;
    }

    /** MOVE SPACES to an alphanumeric item of len bytes at off within group g. */
    private void spaces(Field g, int off, int len) {
        Cobol.moveFigurative(Figurative.SPACES, Field.alphanumeric(g.storage(), g.offset() + off, len, false), CS);
    }

    /** MOVE ZEROS to a zoned item within group g. */
    private void zonedZeros(Field g, int off, int digits, int scale, boolean signed) {
        Cobol.moveFigurative(Figurative.ZEROS, Field.zoned(g.storage(), g.offset() + off, digits, scale, signed, false, false), CS);
    }

    /** MOVE ZEROS to a 9-digit binary item within group g. */
    private void binaryZeros(Field g, int off) {
        Cobol.moveFigurative(Figurative.ZEROS, Field.binary(g.storage(), g.offset() + off, 9, 0, true, false), CS);
    }

    /** MOVE ZEROS to a packed item within group g. */
    private void packedZeros(Field g, int off) {
        Cobol.moveFigurative(Figurative.ZEROS, Field.packed(g.storage(), g.offset() + off, 4, 0, true), CS);
    }

