    /**
     * COMMON-RETURN: copies the return message into the error message area,
     * builds the COMMAREA (common area followed by this program's own area)
     * and returns to CICS with the program's own transaction id.
     */
    private int p1() {
        // MOVE WS-RETURN-MSG TO CCARD-ERROR-MSG
        Cobol.move(f212_WS_RETURN_MSG, f250_CCARD_ERROR_MSG, CS);
        // MOVE CARDDEMO-COMMAREA TO WS-COMMAREA
        Cobol.move(f1123_CARDDEMO_COMMAREA, f1297_WS_COMMAREA, CS);
        // MOVE WS-THIS-PROGCOMMAREA TO WS-COMMAREA(LENGTH OF CARDDEMO-COMMAREA + 1: LENGTH OF WS-THIS-PROGCOMMAREA )
        Cobol.move(f1145_WS_THIS_PROGCOMMAREA, f1297_WS_COMMAREA.ref(BigDecimal.valueOf(160).add(D1).intValue(), Integer.valueOf(BigDecimal.valueOf(873).intValue())), CS);
        // EXEC CICS RETURN TRANSID (LIT-THISTRANID) COMMAREA (WS-COMMAREA) LENGTH(LENGTH OF WS-COMMAREA) END-EXEC
        caBack.run();
        task.returnTransid(Cobol.text(f215_LIT_THISTRANID, CS).strip(), out_CoactupcCommarea(f1297_WS_COMMAREA.storage(), f1297_WS_COMMAREA.offset()), BigDecimal.valueOf(2000).intValue());
        throw new Goback();
    }

