    /** Copies one typed screen value into its input field and length field, if present. */
    private void receiveTyped(java.util.Map<String, String> typed, String name, Field data, Field length) {
        String value = typed.get(name);
        if (value != null) {
            DetCics.typed(data, length, value, CS);
        }
    }

    /**
     * INITIALIZE ACUP-NEW-DETAILS: every elementary item of the group is
     * alphanumeric, so each one is set to spaces, in storage order.
     */
    private void initializeNewDetails() {
        // {offset, length} of each elementary item within ACUP-NEW-DETAILS
        int[][] items = {
            {0, 11}, {11, 1}, {12, 12}, {24, 12}, {36, 12}, {48, 8}, {56, 8}, {64, 8},
            {72, 12}, {84, 12}, {96, 10}, {106, 9}, {115, 25}, {140, 25}, {165, 25},
            {190, 50}, {240, 50}, {290, 50}, {340, 2}, {342, 3}, {345, 10}, {355, 15},
            {370, 15}, {385, 3}, {388, 2}, {390, 4}, {394, 20}, {414, 8}, {422, 10},
            {432, 1}, {433, 3}
        };
        for (int[] item : items) {
            moveSpacesToNewDetailsItem(item[0], item[1]);
        }
    }

    /** MOVE SPACES to the alphanumeric item at the given offset/length within ACUP-NEW-DETAILS. */
    private void moveSpacesToNewDetailsItem(int offset, int length) {
        Field item = Field.alphanumeric(f1221_ACUP_NEW_DETAILS.storage(), f1221_ACUP_NEW_DETAILS.offset() + offset, length, false);
        Cobol.moveFigurative(Figurative.SPACES, item, CS);
    }

    /** True when the screen field is '*' (unchanged marker) or spaces (blank). */
    private boolean isStarOrSpaces(Field screen) {
        return Cobol.compare(screen, "*", CS) == 0
                || Cobol.compareFigurative(screen, Figurative.SPACES, CS) == 0;
    }

    /** Moves the screen field to the target, or LOW-VALUES when it is '*' or spaces. */
    private void moveOrLowValues(Field screen, Field target) {
        if (isStarOrSpaces(screen)) {
            Cobol.moveFigurative(Figurative.LOW_VALUES, target, CS);
        } else {
            Cobol.move(screen, target, CS);
        }
    }

    /**
     * Moves an amount from the screen to its text item (or LOW-VALUES); when the text
     * passes TEST-NUMVAL-C, also stores NUMVAL-C of numvalSource into the numeric item.
     */
    private void moveAmount(Field screen, Field textItem, Field numvalSource, Field numericItem) {
        if (isStarOrSpaces(screen)) {
            Cobol.moveFigurative(Figurative.LOW_VALUES, textItem, CS);
        } else {
            Cobol.move(screen, textItem, CS);
            // IF FUNCTION TEST-NUMVAL-C(text item) = 0
            if (Funcs.testNumvalC(Cobol.text(textItem, CS)).compareTo(D0) == 0) {
                BigDecimal value = Funcs.numvalC(Cobol.text(numvalSource, CS));
                Cobol.store(numericItem, value, false, CS);
            }
        }
    }

