    /**
     * 1200-EDIT-MAP-INPUTS: validates the account-update screen inputs.
     * If the details have not been fetched yet, only the account filter is edited
     * and the paragraph exits. Otherwise the old and new data are compared; when
     * nothing changed (or the change is already confirmed/done) the non-key flags
     * are cleared and the paragraph exits. If there are changes, every editable
     * field is validated and the action becomes "changes OK, not confirmed" unless
     * an input error was flagged.
     */
    private int p7() {
        // SET INPUT-OK TO TRUE
        Cobol.move("0", f89_WS_INPUT_FLAG, CS);
        // IF ACUP-DETAILS-NOT-FETCHED
        if (isDetailsNotFetched()) {
            // PERFORM 1210-EDIT-ACCOUNT THRU 1210-EDIT-ACCOUNT-EXIT
            perform(11, 12);
            // MOVE LOW-VALUES TO ACUP-OLD-ACCT-DATA
            Cobol.moveFigurative(Figurative.LOW_VALUES, f1149_ACUP_OLD_ACCT_DATA, CS);
            // IF FLG-ACCTFILTER-BLANK
            if (Cobol.compare(f92_WS_EDIT_ACCT_FLAG, " ", CS) == 0) {
                // SET NO-SEARCH-CRITERIA-RECEIVED TO TRUE
                Cobol.move("No input received", f212_WS_RETURN_MSG, CS);
            }
            // GO TO 1200-EDIT-MAP-INPUTS-EXIT
            return GOTO | 8;
        }
        // SET FOUND-ACCOUNT-DATA TO TRUE
        Cobol.move("Details of selected account shown above", f211_WS_INFO_MSG, CS);
        // SET FOUND-ACCT-IN-MASTER TO TRUE
        Cobol.move("1", f159_WS_ACCOUNT_MASTER_READ_FLAG, CS);
        // SET FLG-ACCTFILTER-ISVALID TO TRUE
        Cobol.move("1", f92_WS_EDIT_ACCT_FLAG, CS);
        // SET FOUND-CUST-IN-MASTER TO TRUE
        Cobol.move("1", f160_WS_CUST_MASTER_READ_FLAG, CS);
        // SET FLG-CUSTFILTER-ISVALID TO TRUE
        Cobol.move("1", f93_WS_EDIT_CUST_FLAG, CS);
        // PERFORM 1205-COMPARE-OLD-NEW THRU 1205-COMPARE-OLD-NEW-EXIT
        perform(9, 10);
        // IF NO-CHANGES-FOUND OR ACUP-CHANGES-OK-NOT-CONFIRMED OR ACUP-CHANGES-OKAYED-AND-DONE
        if (isNothingToEdit()) {
            // MOVE LOW-VALUES TO WS-NON-KEY-FLAGS
            Cobol.moveFigurative(Figurative.LOW_VALUES, f94_WS_NON_KEY_FLAGS, CS);
            // GO TO 1200-EDIT-MAP-INPUTS-EXIT
            return GOTO | 8;
        }
        // SET ACUP-CHANGES-NOT-OK TO TRUE
        Cobol.move("E", f1147_ACUP_CHANGE_ACTION, CS);

        // Account Status
        Cobol.move("Account Status", f8_WS_EDIT_VARIABLE_NAME, CS);
        Cobol.move(f1225_ACUP_NEW_ACTIVE_STATUS, f16_WS_EDIT_YES_NO, CS);
        perform(15, 16);
        Cobol.move(f16_WS_EDIT_YES_NO, f95_WS_EDIT_ACCT_STATUS, CS);

        editDate("Open Date", f1232_ACUP_NEW_OPEN_DATE, f106_WS_EDIT_OPEN_DATE_FLGS);
        editSignedAmount("Credit Limit", f172_ACUP_NEW_CREDIT_LIMIT_X, f96_WS_EDIT_CREDIT_LIMIT);
        editDate("Expiry Date", f1237_ACUP_NEW_EXPIRAION_DATE, f110_WS_EXPIRY_DATE_FLGS);
        editSignedAmount("Cash Credit Limit", f173_ACUP_NEW_CASH_CREDIT_LIMIT_X, f97_WS_EDIT_CASH_CREDIT_LIMIT);
        editDate("Reissue Date", f1242_ACUP_NEW_REISSUE_DATE, f114_WS_EDIT_REISSUE_DATE_FLGS);
        editSignedAmount("Current Balance", f174_ACUP_NEW_CURR_BAL_X, f98_WS_EDIT_CURR_BAL);
        editSignedAmount("Current Cycle Credit Limit", f175_ACUP_NEW_CURR_CYC_CREDIT_X, f99_WS_EDIT_CURR_CYC_CREDIT);
        editSignedAmount("Current Cycle Debit Limit", f176_ACUP_NEW_CURR_CYC_DEBIT_X, f100_WS_EDIT_CURR_CYC_DEBIT);

        // SSN
        Cobol.move("SSN", f8_WS_EDIT_VARIABLE_NAME, CS);
        perform(35, 36);

        editDate("Date of Birth", f1288_ACUP_NEW_CUST_DOB_YYYY_MM_DD, f101_WS_EDIT_DT_OF_BIRTH_FLGS);
        // IF WS-EDIT-DT-OF-BIRTH-ISVALID
        if (Cobol.compareFigurative(f101_WS_EDIT_DT_OF_BIRTH_FLGS, Figurative.LOW_VALUES, CS) == 0) {
            // PERFORM EDIT-DATE-OF-BIRTH THRU EDIT-DATE-OF-BIRTH-EXIT
            perform(99, 100);
            Cobol.move(f67_WS_EDIT_DATE_FLGS, f101_WS_EDIT_DT_OF_BIRTH_FLGS, CS);
        }

        // FICO Score
        loadAlphanum("FICO Score", f1295_ACUP_NEW_CUST_FICO_SCORE_X, D3);
        perform(25, 26);
        Cobol.move(f14_WS_EDIT_ALPHANUM_ONLY_FLAGS, f105_WS_EDIT_FICO_SCORE_FLGS, CS);
        // IF FLG-FICO-SCORE-ISVALID
        if (Cobol.compareFigurative(f105_WS_EDIT_FICO_SCORE_FLGS, Figurative.LOW_VALUES, CS) == 0) {
            // PERFORM 1275-EDIT-FICO-SCORE THRU 1275-EDIT-FICO-SCORE-EXIT
            perform(39, 40);
        }

        // First Name (required alpha)
        loadAlphanum("First Name", f1255_ACUP_NEW_CUST_FIRST_NAME, D25);
        perform(17, 18);
        Cobol.move(f13_WS_EDIT_ALPHA_ONLY_FLAGS, f119_WS_EDIT_FIRST_NAME_FLGS, CS);

        // Middle Name (optional alpha)
        loadAlphanum("Middle Name", f1256_ACUP_NEW_CUST_MIDDLE_NAME, D25);
        perform(21, 22);
        Cobol.move(f13_WS_EDIT_ALPHA_ONLY_FLAGS, f120_WS_EDIT_MIDDLE_NAME_FLGS, CS);

        // Last Name (required alpha)
        loadAlphanum("Last Name", f1257_ACUP_NEW_CUST_LAST_NAME, D25);
        perform(17, 18);
        Cobol.move(f13_WS_EDIT_ALPHA_ONLY_FLAGS, f121_WS_EDIT_LAST_NAME_FLGS, CS);

        // Address Line 1 (mandatory)
        loadAlphanum("Address Line 1", f1258_ACUP_NEW_CUST_ADDR_LINE_1, D50);
        perform(13, 14);
        Cobol.move(f15_WS_EDIT_MANDATORY_FLAGS, f123_WS_EDIT_ADDRESS_LINE_1_FLGS, CS);

        // State (required alpha)
        loadAlphanum("State", f1261_ACUP_NEW_CUST_ADDR_STATE_CD, D2);
        perform(17, 18);
        Cobol.move(f13_WS_EDIT_ALPHA_ONLY_FLAGS, f126_WS_EDIT_STATE_FLGS, CS);
        // IF FLG-ALPHA-ISVALID
        if (Cobol.compareFigurative(f13_WS_EDIT_ALPHA_ONLY_FLAGS, Figurative.LOW_VALUES, CS) == 0) {
            // PERFORM 1270-EDIT-US-STATE-CD THRU 1270-EDIT-US-STATE-CD-EXIT
            perform(37, 38);
        }

        // Zip (required numeric)
        loadAlphanum("Zip", f1263_ACUP_NEW_CUST_ADDR_ZIP, D5);
        perform(25, 26);
        Cobol.move(f14_WS_EDIT_ALPHANUM_ONLY_FLAGS, f127_WS_EDIT_ZIPCODE_FLGS, CS);

        // City (required alpha)
        loadAlphanum("City", f1260_ACUP_NEW_CUST_ADDR_LINE_3, D50);
        perform(17, 18);
        Cobol.move(f13_WS_EDIT_ALPHA_ONLY_FLAGS, f125_WS_EDIT_CITY_FLGS, CS);

        // Country (required alpha)
        loadAlphanum("Country", f1262_ACUP_NEW_CUST_ADDR_COUNTRY_CD, D3);
        perform(17, 18);
        Cobol.move(f13_WS_EDIT_ALPHA_ONLY_FLAGS, f128_WS_EDIT_COUNTRY_FLGS, CS);

        editPhone("Phone Number 1", f1264_ACUP_NEW_CUST_PHONE_NUM_1, f129_WS_EDIT_PHONE_NUM_1_FLGS);
        editPhone("Phone Number 2", f1273_ACUP_NEW_CUST_PHONE_NUM_2, f133_WS_EDIT_PHONE_NUM_2_FLGS);

        // EFT Account Id (required numeric)
        loadAlphanum("EFT Account Id", f1293_ACUP_NEW_CUST_EFT_ACCOUNT_ID, D10);
        perform(25, 26);
        Cobol.move(f14_WS_EDIT_ALPHANUM_ONLY_FLAGS, f137_WS_EFT_ACCOUNT_ID_FLGS, CS);

        // Primary Card Holder
        Cobol.move("Primary Card Holder", f8_WS_EDIT_VARIABLE_NAME, CS);
        Cobol.move(f1294_ACUP_NEW_CUST_PRI_HOLDER_IND, f16_WS_EDIT_YES_NO, CS);
        perform(15, 16);
        Cobol.move(f16_WS_EDIT_YES_NO, f138_WS_EDIT_PRI_CARDHOLDER, CS);

        // IF FLG-STATE-ISVALID AND FLG-ZIPCODE-ISVALID
        if (Cobol.compareFigurative(f126_WS_EDIT_STATE_FLGS, Figurative.LOW_VALUES, CS) == 0
                && Cobol.compareFigurative(f127_WS_EDIT_ZIPCODE_FLGS, Figurative.LOW_VALUES, CS) == 0) {
            // PERFORM 1280-EDIT-US-STATE-ZIP-CD THRU 1280-EDIT-US-STATE-ZIP-CD-EXIT
            perform(41, 42);
        }
        // IF NOT INPUT-ERROR
        if (Cobol.compare(f89_WS_INPUT_FLAG, "1", CS) != 0) {
            // SET ACUP-CHANGES-OK-NOT-CONFIRMED TO TRUE
            Cobol.move("N", f1147_ACUP_CHANGE_ACTION, CS);
        }
        return 8;
    }

    /** ACUP-DETAILS-NOT-FETCHED: change action is low-values or spaces. */
    private boolean isDetailsNotFetched() {
        return Cobol.compareFigurative(f1147_ACUP_CHANGE_ACTION, Figurative.LOW_VALUES, CS) == 0
                || Cobol.compareFigurative(f1147_ACUP_CHANGE_ACTION, Figurative.SPACES, CS) == 0;
    }

    /** NO-CHANGES-FOUND, ACUP-CHANGES-OK-NOT-CONFIRMED or ACUP-CHANGES-OKAYED-AND-DONE. */
    private boolean isNothingToEdit() {
        return Cobol.compare(f88_WS_DATACHANGED_FLAG, "0", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "N", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "C", CS) == 0;
    }

