    /**
     * EDIT-US-PHONE-PREFIX: validates the 3-digit US phone prefix.
     * It must be supplied, numeric and non-zero. On failure it flags the input
     * as in error, sets the prefix flag, sets the return message if none is
     * set yet, and goes to EDIT-US-PHONE-LINENUM.
     */
    private int p31() {
        // IF WS-EDIT-US-PHONE-NUMB EQUAL SPACES OR LOW-VALUES
        if (Cobol.compareFigurative(f23_WS_EDIT_US_PHONE_NUMB, Figurative.SPACES, CS) == 0
                || Cobol.compareFigurative(f23_WS_EDIT_US_PHONE_NUMB, Figurative.LOW_VALUES, CS) == 0) {
            p31Reject("B", ": Prefix code must be supplied.");
            return GOTO | 32;
        }
        // IF WS-EDIT-US-PHONE-NUMB IS NOT NUMERIC
        if (!Cobol.isNumeric(f23_WS_EDIT_US_PHONE_NUMB, CS)) {
            p31Reject("0", ": Prefix code must be A 3 digit number.");
            return GOTO | 32;
        }
        // IF WS-EDIT-US-PHONE-NUMB-N = 0
        if (Cobol.num(f24_WS_EDIT_US_PHONE_NUMB_N, CS).compareTo(D0) == 0) {
            p31Reject("0", ": Prefix code cannot be zero");
            return GOTO | 32;
        }
        // SET FLG-EDIT-US-PHONEB-ISVALID TO TRUE
        Cobol.moveFigurative(Figurative.LOW_VALUES, f31_WS_EDIT_EDIT_US_PHONEB, CS);
        return 32;
    }

    /** Sets INPUT-ERROR and the prefix flag; fills WS-RETURN-MSG with the variable name and text if the message is off. */
    private void p31Reject(String prefixFlag, String messageText) {
        // SET INPUT-ERROR TO TRUE
        Cobol.move("1", f89_WS_INPUT_FLAG, CS);
        // SET FLG-EDIT-US-PHONEB-xxx TO TRUE
        Cobol.move(prefixFlag, f31_WS_EDIT_EDIT_US_PHONEB, CS);
        // IF WS-RETURN-MSG-OFF
        if (Cobol.compareFigurative(f212_WS_RETURN_MSG, Figurative.SPACES, CS) == 0) {
            // STRING FUNCTION TRIM(WS-EDIT-VARIABLE-NAME) message DELIMITED BY SIZE INTO WS-RETURN-MSG
            Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size(Funcs.trim(Cobol.text(f8_WS_EDIT_VARIABLE_NAME, CS)), CS), Cobol.StringPart.size(messageText, CS));
        }
    }

    /**
     * EDIT-US-PHONE-LINENUM: validates the 4-character line number part of a
     * US phone number. It must be supplied, numeric, and non-zero. On any
     * failure it flags the input as in error, sets the edit status, sets the
     * return message if none is set yet, and jumps to EDIT-US-PHONE-EXIT.
     * Otherwise it marks the field valid and falls through.
     */
    private int p32() {
        // IF WS-EDIT-US-PHONE-NUMC EQUAL SPACES OR WS-EDIT-US-PHONE-NUMC EQUAL LOW-VALUES
        if (Cobol.compareFigurative(f26_WS_EDIT_US_PHONE_NUMC, Figurative.SPACES, CS) == 0
                || Cobol.compareFigurative(f26_WS_EDIT_US_PHONE_NUMC, Figurative.LOW_VALUES, CS) == 0) {
            rejectLineNumber("B", ": Line number code must be supplied.");
            return GOTO | 33;
        }
        // IF WS-EDIT-US-PHONE-NUMC IS NUMERIC
        if (!Cobol.isNumeric(f26_WS_EDIT_US_PHONE_NUMC, CS)) {
            rejectLineNumber("0", ": Line number code must be A 4 digit number.");
            return GOTO | 33;
        }
        // IF WS-EDIT-US-PHONE-NUMC-N = 0
        if (Cobol.num(f27_WS_EDIT_US_PHONE_NUMC_N, CS).compareTo(D0) == 0) {
            rejectLineNumber("0", ": Line number code cannot be zero");
            return GOTO | 33;
        }
        // SET FLG-EDIT-US-PHONEC-ISVALID TO TRUE
        Cobol.moveFigurative(Figurative.LOW_VALUES, f32_WS_EDIT_EDIT_PHONEC, CS);
        return 33;
    }

    /** Common error handling: SET INPUT-ERROR, set the phone status flag, and set the message if still off. */
    private void rejectLineNumber(String statusFlag, String message) {
        // SET INPUT-ERROR TO TRUE
        Cobol.move("1", f89_WS_INPUT_FLAG, CS);
        // SET FLG-EDIT-US-PHONEC-BLANK / NOT-OK TO TRUE
        Cobol.move(statusFlag, f32_WS_EDIT_EDIT_PHONEC, CS);
        // IF WS-RETURN-MSG-OFF
        if (Cobol.compareFigurative(f212_WS_RETURN_MSG, Figurative.SPACES, CS) == 0) {
            // STRING FUNCTION TRIM(WS-EDIT-VARIABLE-NAME) message DELIMITED BY SIZE INTO WS-RETURN-MSG
            Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size(Funcs.trim(Cobol.text(f8_WS_EDIT_VARIABLE_NAME, CS)), CS), Cobol.StringPart.size(message, CS));
        }
    }

