    /**
     * 1265-EDIT-US-SSN: validates the three parts of the US SSN. The first
     * part is checked as a required number and, if valid, must not be 000,
     * 666 or 900-999. The 2nd and 3rd parts are then checked as required
     * numbers, with their flags kept in the part 2 / part 3 flag fields.
     */
    private int p35() {
        // MOVE 'SSN: First 3 chars' TO WS-EDIT-VARIABLE-NAME
        Cobol.move("SSN: First 3 chars", f8_WS_EDIT_VARIABLE_NAME, CS);
        // MOVE ACUP-NEW-CUST-SSN-1 TO WS-EDIT-ALPHANUM-ONLY
        Cobol.move(f1283_ACUP_NEW_CUST_SSN_1, f11_WS_EDIT_ALPHANUM_ONLY, CS);
        // MOVE 3 TO WS-EDIT-ALPHANUM-LENGTH
        Cobol.move(D3, f12_WS_EDIT_ALPHANUM_LENGTH, CS);
        // PERFORM 1245-EDIT-NUM-REQD THRU 1245-EDIT-NUM-REQD-EXIT
        perform(25, 26);
        // MOVE WS-EDIT-ALPHANUM-ONLY-FLAGS TO WS-EDIT-US-SSN-PART1-FLGS
        Cobol.move(f14_WS_EDIT_ALPHANUM_ONLY_FLAGS, f42_WS_EDIT_US_SSN_PART1_FLGS, CS);
        // IF FLG-EDIT-US-SSN-PART1-ISVALID
        if (Cobol.compareFigurative(f42_WS_EDIT_US_SSN_PART1_FLGS, Figurative.LOW_VALUES, CS) == 0) {
            // MOVE ACUP-NEW-CUST-SSN-1 TO WS-EDIT-US-SSN-PART1
            Cobol.move(f1283_ACUP_NEW_CUST_SSN_1, f34_WS_EDIT_US_SSN_PART1, CS);
            // IF INVALID-SSN-PART1
            if (isInvalidSsnPart1()) {
                // SET INPUT-ERROR TO TRUE
                Cobol.move("1", f89_WS_INPUT_FLAG, CS);
                // SET FLG-EDIT-US-SSN-PART1-NOT-OK TO TRUE
                Cobol.move("0", f42_WS_EDIT_US_SSN_PART1_FLGS, CS);
                // IF WS-RETURN-MSG-OFF
                if (Cobol.compareFigurative(f212_WS_RETURN_MSG, Figurative.SPACES, CS) == 0) {
                    // STRING FUNCTION TRIM(WS-EDIT-VARIABLE-NAME) ': should not be 000, 666, or between 900 and 999' DELIMITED BY SIZE INTO WS-RETURN-MSG
                    Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size(Funcs.trim(Cobol.text(f8_WS_EDIT_VARIABLE_NAME, CS)), CS), Cobol.StringPart.size(": should not be 000, 666, or between 900 and 999", CS));
                }
            }
            // MOVE 'SSN 4th & 5th chars' TO WS-EDIT-VARIABLE-NAME
            Cobol.move("SSN 4th & 5th chars", f8_WS_EDIT_VARIABLE_NAME, CS);
            // MOVE ACUP-NEW-CUST-SSN-2 TO WS-EDIT-ALPHANUM-ONLY
            Cobol.move(f1284_ACUP_NEW_CUST_SSN_2, f11_WS_EDIT_ALPHANUM_ONLY, CS);
            // MOVE 2 TO WS-EDIT-ALPHANUM-LENGTH
            Cobol.move(D2, f12_WS_EDIT_ALPHANUM_LENGTH, CS);
            // PERFORM 1245-EDIT-NUM-REQD THRU 1245-EDIT-NUM-REQD-EXIT
            perform(25, 26);
            // MOVE WS-EDIT-ALPHANUM-ONLY-FLAGS TO WS-EDIT-US-SSN-PART2-FLGS
            Cobol.move(f14_WS_EDIT_ALPHANUM_ONLY_FLAGS, f43_WS_EDIT_US_SSN_PART2_FLGS, CS);
            // MOVE 'SSN Last 4 chars' TO WS-EDIT-VARIABLE-NAME
            Cobol.move("SSN Last 4 chars", f8_WS_EDIT_VARIABLE_NAME, CS);
            // MOVE ACUP-NEW-CUST-SSN-3 TO WS-EDIT-ALPHANUM-ONLY
            Cobol.move(f1285_ACUP_NEW_CUST_SSN_3, f11_WS_EDIT_ALPHANUM_ONLY, CS);
            // MOVE 4 TO WS-EDIT-ALPHANUM-LENGTH
            Cobol.move(D4, f12_WS_EDIT_ALPHANUM_LENGTH, CS);
            // PERFORM 1245-EDIT-NUM-REQD THRU 1245-EDIT-NUM-REQD-EXIT
            perform(25, 26);
            // MOVE WS-EDIT-ALPHANUM-ONLY-FLAGS TO WS-EDIT-US-SSN-PART3-FLGS
            Cobol.move(f14_WS_EDIT_ALPHANUM_ONLY_FLAGS, f44_WS_EDIT_US_SSN_PART3_FLGS, CS);
        }
        return 36;
    }

    /** INVALID-SSN-PART1: the first SSN part is 000, 666 or 900-999. */
    private boolean isInvalidSsnPart1() {
        return Cobol.compare(f35_WS_EDIT_US_SSN_PART1_N, D0, CS) == 0
                || Cobol.compare(f35_WS_EDIT_US_SSN_PART1_N, D666, CS) == 0
                || (Cobol.compare(f35_WS_EDIT_US_SSN_PART1_N, D900, CS) >= 0
                    && Cobol.compare(f35_WS_EDIT_US_SSN_PART1_N, D999, CS) <= 0);
    }

