                Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size(Funcs.trim(Cobol.text(f8_WS_EDIT_VARIABLE_NAME, CS)), CS), Cobol.StringPart.size(": is not a valid state code", CS));
