        boolean ficoInRange = Cobol.compare(f1296_ACUP_NEW_CUST_FICO_SCORE, D300, CS) >= 0
                && Cobol.compare(f1296_ACUP_NEW_CUST_FICO_SCORE, D850, CS) <= 0;
