    /**
     * 1280-EDIT-US-STATE-ZIP-CD.
     * Combines the state code with the first two digits of the ZIP code and checks
     * that the pair is a valid US state/ZIP-prefix combination. If not, flags the
     * input, state and ZIP code as in error, sets the "Invalid zip code for state"
     * message when no message is set yet, and goes to the paragraph exit.
     */
    private int p41() {
        // STRING ACUP-NEW-CUST-ADDR-STATE-CD ACUP-NEW-CUST-ADDR-ZIP(1:2) DELIMITED BY SIZE INTO US-STATE-AND-FIRST-ZIP2
        Cobol.string(f261_US_STATE_AND_FIRST_ZIP2, null, CS, Cobol.StringPart.size(f1261_ACUP_NEW_CUST_ADDR_STATE_CD), Cobol.StringPart.size(f1263_ACUP_NEW_CUST_ADDR_ZIP.ref(1, Integer.valueOf(2))));
        // IF VALID-US-STATE-ZIP-CD2-COMBO
        if (isValidUsStateZipCd2Combo()) {
            // CONTINUE
            return 42;
        }
        // SET INPUT-ERROR TO TRUE
        Cobol.move("1", f89_WS_INPUT_FLAG, CS);
        // SET FLG-STATE-NOT-OK TO TRUE
        Cobol.move("0", f126_WS_EDIT_STATE_FLGS, CS);
        // SET FLG-ZIPCODE-NOT-OK TO TRUE
        Cobol.move("0", f127_WS_EDIT_ZIPCODE_FLGS, CS);
        // IF WS-RETURN-MSG-OFF
        if (Cobol.compareFigurative(f212_WS_RETURN_MSG, Figurative.SPACES, CS) == 0) {
            // STRING 'Invalid zip code for state' DELIMITED BY SIZE INTO WS-RETURN-MSG
            Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size("Invalid zip code for state", CS));
        }
        // GO TO 1280-EDIT-US-STATE-ZIP-CD-EXIT
        return GOTO | 42;
    }

