    /**
     * 3200-SETUP-SCREEN-VARS.
     * Fills the account-id field and the data fields of the account update
     * screen. On first entry to the program nothing is set up; otherwise the
     * account id is shown (blank if the filter was valid but zero) and the
     * initial, original or updated values are displayed depending on the
     * current change action.
     */
    private int p49() {
        // IF CDEMO-PGM-ENTER
        if (Cobol.compare(f1131_CDEMO_PGM_CONTEXT, D0, CS) == 0) {
            // CONTINUE
            return 50;
        }
        if (isAcctIdZeroAndFilterValid()) {
            // MOVE LOW-VALUES TO ACCTSIDO OF CACTUPAO
            Cobol.moveFigurative(Figurative.LOW_VALUES, f747_ACCTSIDO, CS);
        } else {
            // MOVE CC-ACCT-ID TO ACCTSIDO OF CACTUPAO
            Cobol.move(f252_CC_ACCT_ID, f747_ACCTSIDO, CS);
        }
        // EVALUATE TRUE
        if (isChangeActionEmpty() || isAcctIdZero()) {
            // PERFORM 3201-SHOW-INITIAL-VALUES THRU 3201-SHOW-INITIAL-VALUES-EXIT
            perform(51, 52);
        } else if (Cobol.compare(f1147_ACUP_CHANGE_ACTION, "S", CS) == 0) {
            // PERFORM 3202-SHOW-ORIGINAL-VALUES THRU 3202-SHOW-ORIGINAL-VALUES-EXIT
            perform(53, 54);
        } else if (isChangeActionUpdated()) {
            // PERFORM 3203-SHOW-UPDATED-VALUES THRU 3203-SHOW-UPDATED-VALUES-EXIT
            perform(55, 56);
        } else {
            // PERFORM 3202-SHOW-ORIGINAL-VALUES THRU 3202-SHOW-ORIGINAL-VALUES-EXIT
            perform(53, 54);
        }
        return 50;
    }

    private boolean isAcctIdZero() {
        return Cobol.num(f253_CC_ACCT_ID_N, CS).compareTo(D0) == 0;
    }

    private boolean isAcctIdZeroAndFilterValid() {
        return isAcctIdZero() && Cobol.compare(f92_WS_EDIT_ACCT_FLAG, "1", CS) == 0;
    }

    private boolean isChangeActionEmpty() {
        return Cobol.compareFigurative(f1147_ACUP_CHANGE_ACTION, Figurative.LOW_VALUES, CS) == 0
            || Cobol.compareFigurative(f1147_ACUP_CHANGE_ACTION, Figurative.SPACES, CS) == 0;
    }

    private boolean isChangeActionUpdated() {
        return Cobol.compare(f1147_ACUP_CHANGE_ACTION, "E", CS) == 0
            || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "N", CS) == 0
            || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "C", CS) == 0
            || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "L", CS) == 0
            || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "F", CS) == 0;
    }

