    /** True when the field compares equal to the literal (space-padded alphanumeric compare). */
    private boolean p59FlagEq(Field f, String literal) {
        return Cobol.compare(f, literal, CS) == 0;
    }

    /** ACUP-DETAILS-NOT-FETCHED: change action is LOW-VALUES or SPACES. */
    private boolean p59ChangeActionUnset() {
        return Cobol.compareFigurative(f1147_ACUP_CHANGE_ACTION, Figurative.LOW_VALUES, CS) == 0
                || Cobol.compareFigurative(f1147_ACUP_CHANGE_ACTION, Figurative.SPACES, CS) == 0;
    }

    /** Edit flag is NOT-OK ('0') or BLANK ('B'). */
    private boolean p59NotOkOrBlank(Field flag) {
        return p59FlagEq(flag, "0") || p59FlagEq(flag, "B");
    }

    /** CDEMO-PGM-REENTER. */
    private boolean p59IsReenter() {
        return Cobol.compare(f1131_CDEMO_PGM_CONTEXT, D1, CS) == 0;
    }

    /** On re-entry, colours an invalid field red and puts '*' in it when it was left blank. */
    private void p59MarkError(Field flag, Field colour, Field output) {
        if (p59NotOkOrBlank(flag) && p59IsReenter()) {
            Cobol.move(f302_DFHRED, colour, CS);
            if (p59FlagEq(flag, "B")) {
                Cobol.move("*", output, CS);
            }
        }
    }

