    /**
     * 3390-SETUP-INFOMSG-ATTRS: sets the display attributes of the info message
     * and the F5/F12 function-key labels on the account update screen.
     */
    private int p65() {
        // IF WS-NO-INFO-MESSAGE
        if (isNoInfoMessage()) {
            // MOVE DFHBMDAR TO INFOMSGA OF CACTUPAI
            Cobol.move(f279_DFHBMDAR, f677_INFOMSGA, CS);
        } else {
            // MOVE DFHBMASB TO INFOMSGA OF CACTUPAI
            Cobol.move(f283_DFHBMASB, f677_INFOMSGA, CS);
        }
        // IF ACUP-CHANGES-MADE AND NOT ACUP-CHANGES-OKAYED-AND-DONE
        if (isChangesMade() && !isChangesOkayedAndDone()) {
            // MOVE DFHBMASB TO FKEY12A OF CACTUPAI
            Cobol.move(f283_DFHBMASB, f701_FKEY12A, CS);
        }
        // IF PROMPT-FOR-CONFIRMATION
        if (Cobol.compare(f211_WS_INFO_MSG, "Changes validated.Press F5 to save", CS) == 0) {
            // MOVE DFHBMASB TO FKEY05A OF CACTUPAI
            Cobol.move(f283_DFHBMASB, f695_FKEY05A, CS);
            // MOVE DFHBMASB TO FKEY12A OF CACTUPAI
            Cobol.move(f283_DFHBMASB, f701_FKEY12A, CS);
        }
        return 66;
    }

    private boolean isNoInfoMessage() {
        return Cobol.compareFigurative(f211_WS_INFO_MSG, Figurative.SPACES, CS) == 0
                || Cobol.compareFigurative(f211_WS_INFO_MSG, Figurative.LOW_VALUES, CS) == 0;
    }

    private boolean isChangesMade() {
        return Cobol.compare(f1147_ACUP_CHANGE_ACTION, "E", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "N", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "C", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "L", CS) == 0
                || Cobol.compare(f1147_ACUP_CHANGE_ACTION, "F", CS) == 0;
    }

    private boolean isChangesOkayedAndDone() {
        return Cobol.compare(f1147_ACUP_CHANGE_ACTION, "C", CS) == 0;
    }

