        Cobol.move(f1113_CUST_ADDR_ZIP, f1190_ACUP_OLD_CUST_ADDR_ZIP, CS);
        // MOVE CUST-PHONE-NUM-1 TO ACUP-OLD-CUST-PHONE-NUM-1
        Cobol.move(f1114_CUST_PHONE_NUM_1, f1191_ACUP_OLD_CUST_PHONE_NUM_1, CS);
        // MOVE CUST-PHONE-NUM-2 TO ACUP-OLD-CUST-PHONE-NUM-2
        Cobol.move(f1115_CUST_PHONE_NUM_2, f1200_ACUP_OLD_CUST_PHONE_NUM_2, CS);
        // MOVE CUST-GOVT-ISSUED-ID TO ACUP-OLD-CUST-GOVT-ISSUED-ID
        Cobol.move(f1117_CUST_GOVT_ISSUED_ID, f1211_ACUP_OLD_CUST_GOVT_ISSUED_ID, CS);
        // MOVE CUST-EFT-ACCOUNT-ID TO ACUP-OLD-CUST-EFT-ACCOUNT-ID
        Cobol.move(f1119_CUST_EFT_ACCOUNT_ID, f1217_ACUP_OLD_CUST_EFT_ACCOUNT_ID, CS);
