    /**
     * ABEND-ROUTINE.
     * Defaults the abend message if none was set, records this program as the
     * culprit, sends the abend data to the terminal (erasing the screen),
     * cancels any active abend handler and abends the task with code 9999.
     */
    private int p85() {
        // IF ABEND-MSG EQUAL LOW-VALUES
        if (Cobol.compareFigurative(f1076_ABEND_MSG, Figurative.LOW_VALUES, CS) == 0) {
            // MOVE 'UNEXPECTED ABEND OCCURRED.' TO ABEND-MSG
            Cobol.move("UNEXPECTED ABEND OCCURRED.", f1076_ABEND_MSG, CS);
        }
        // MOVE LIT-THISPGM TO ABEND-CULPRIT
        Cobol.move(f214_LIT_THISPGM, f1074_ABEND_CULPRIT, CS);
        // EXEC CICS SEND FROM (ABEND-DATA) LENGTH(LENGTH OF ABEND-DATA) NOHANDLE ERASE END-EXEC
        String text25 = Cobol.text(f1072_ABEND_DATA, CS);
        task.sendText(text25.substring(0, Math.min(text25.length(), BigDecimal.valueOf(134).intValue())), BigDecimal.valueOf(134).intValue(), "ERASE");
        Cobol.store(f1329_EIBRESP, BigDecimal.valueOf(0), false, CS);
        Cobol.store(f1330_EIBRESP2, BigDecimal.valueOf(0), false, CS);
        // EXEC CICS HANDLE ABEND CANCEL END-EXEC
        task.handleAbendCancel();
        // EXEC CICS ABEND ABCODE('9999') END-EXEC
        String exit26 = task.abend("9999".strip());
        if (exit26 == null) throw new Goback();
        return GOTO | paragraph(exit26);
    }

