    /**
     * EDIT-YEAR-CCYY: validates the century-and-year part of the edited date.
     * Rejects a blank year, a non-numeric year and a century other than 19 or 20,
     * setting the input-error flag, the year flag and (if no message is set yet)
     * the return message. Rejections jump to EDIT-YEAR-CCYY-EXIT; a valid year
     * sets FLG-YEAR-ISVALID and falls through to it.
     */
    private int p88() {
        // SET FLG-YEAR-NOT-OK TO TRUE
        Cobol.move("0", f68_WS_EDIT_YEAR_FLG, CS);

        if (isP88YearBlank()) {
            p88Reject("B", " : Year must be supplied.");
            return GOTO | 89;
        }

        if (!Cobol.isNumeric(f51_WS_EDIT_DATE_CCYY, CS)) {
            p88Reject("0", " must be 4 digit number.");
            return GOTO | 89;
        }

        // IF THIS-CENTURY OR LAST-CENTURY
        boolean centuryOk = Cobol.compare(f53_WS_EDIT_DATE_CC_N, D20, CS) == 0
                || Cobol.compare(f53_WS_EDIT_DATE_CC_N, D19, CS) == 0;
        if (!centuryOk) {
            p88Reject("0", " : Century is not valid.");
            return GOTO | 89;
        }

        // SET FLG-YEAR-ISVALID TO TRUE
        Cobol.moveFigurative(Figurative.LOW_VALUES, f68_WS_EDIT_YEAR_FLG, CS);
        return 89;
    }

    /** WS-EDIT-DATE-CCYY EQUAL LOW-VALUES OR SPACES. */
    private boolean isP88YearBlank() {
        return Cobol.compareFigurative(f51_WS_EDIT_DATE_CCYY, Figurative.LOW_VALUES, CS) == 0
                || Cobol.compareFigurative(f51_WS_EDIT_DATE_CCYY, Figurative.SPACES, CS) == 0;
    }

