    /**
     * EDIT-MONTH: validates WS-EDIT-DATE-MM. Sets FLG-MONTH-BLANK, FLG-MONTH-NOT-OK
     * or FLG-MONTH-ISVALID, flags INPUT-ERROR and fills WS-RETURN-MSG (if still
     * empty) when the month is missing or is not a number from 1 to 12.
     */
    private int p90() {
        // SET FLG-MONTH-NOT-OK TO TRUE
        Cobol.move("0", f69_WS_EDIT_MONTH, CS);
        // IF WS-EDIT-DATE-MM EQUAL LOW-VALUES OR WS-EDIT-DATE-MM EQUAL SPACES
        if (Cobol.compareFigurative(f57_WS_EDIT_DATE_MM, Figurative.LOW_VALUES, CS) == 0
                || Cobol.compareFigurative(f57_WS_EDIT_DATE_MM, Figurative.SPACES, CS) == 0) {
            p90Reject("B", " : Month must be supplied.");
            return GOTO | 91;
        }
        // IF WS-VALID-MONTH
        if (!(Cobol.compare(f58_WS_EDIT_DATE_MM_N, D1, CS) >= 0 && Cobol.compare(f58_WS_EDIT_DATE_MM_N, D12, CS) <= 0)) {
            p90Reject("0", ": Month must be a number between 1 and 12.");
            return GOTO | 91;
        }
        // IF FUNCTION TEST-NUMVAL (WS-EDIT-DATE-MM) = 0
        if (Funcs.testNumval(Cobol.text(f57_WS_EDIT_DATE_MM, CS)).compareTo(D0) == 0) {
            // COMPUTE WS-EDIT-DATE-MM-N = FUNCTION NUMVAL (WS-EDIT-DATE-MM)
            BigDecimal v27 = Funcs.numval(Cobol.text(f57_WS_EDIT_DATE_MM, CS));
            Cobol.store(f58_WS_EDIT_DATE_MM_N, v27, false, CS);
        } else {
            p90Reject("0", ": Month must be a number between 1 and 12.");
            return GOTO | 91;
        }
        // SET FLG-MONTH-ISVALID TO TRUE
        Cobol.moveFigurative(Figurative.LOW_VALUES, f69_WS_EDIT_MONTH, CS);
        return 91;
    }

    /** Flags INPUT-ERROR, sets the month flag, and builds the message if WS-RETURN-MSG-OFF. */
