    /** EDIT-DAY. Validates WS-EDIT-DATE-DD as a day number from 1 to 31. */
    private int p92() {
        // SET FLG-DAY-ISVALID TO TRUE
        Cobol.moveFigurative(Figurative.LOW_VALUES, f70_WS_EDIT_DAY, CS);
        // IF WS-EDIT-DATE-DD EQUAL LOW-VALUES OR WS-EDIT-DATE-DD EQUAL SPACES
        if (Cobol.compareFigurative(f59_WS_EDIT_DATE_DD, Figurative.LOW_VALUES, CS) == 0
                || Cobol.compareFigurative(f59_WS_EDIT_DATE_DD, Figurative.SPACES, CS) == 0) {
            // SET INPUT-ERROR TO TRUE
            Cobol.move("1", f89_WS_INPUT_FLAG, CS);
            // SET FLG-DAY-BLANK TO TRUE
            Cobol.move("B", f70_WS_EDIT_DAY, CS);
            // IF WS-RETURN-MSG-OFF
            if (isDayReturnMsgOff()) {
                // STRING FUNCTION TRIM(WS-EDIT-VARIABLE-NAME) ' : Day must be supplied.' DELIMITED BY SIZE INTO WS-RETURN-MSG
                Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size(Funcs.trim(Cobol.text(f8_WS_EDIT_VARIABLE_NAME, CS)), CS), Cobol.StringPart.size(" : Day must be supplied.", CS));
            }
            // GO TO EDIT-DAY-EXIT
            return GOTO | 93;
        }
        // IF FUNCTION TEST-NUMVAL (WS-EDIT-DATE-DD) = 0
        if (Funcs.testNumval(Cobol.text(f59_WS_EDIT_DATE_DD, CS)).compareTo(D0) != 0) {
            return rejectDay();
        }
        // COMPUTE WS-EDIT-DATE-DD-N = FUNCTION NUMVAL (WS-EDIT-DATE-DD)
        BigDecimal v28 = Funcs.numval(Cobol.text(f59_WS_EDIT_DATE_DD, CS));
        Cobol.store(f60_WS_EDIT_DATE_DD_N, v28, false, CS);
        // IF WS-VALID-DAY
        if (!(Cobol.compare(f60_WS_EDIT_DATE_DD_N, D1, CS) >= 0 && Cobol.compare(f60_WS_EDIT_DATE_DD_N, D31, CS) <= 0)) {
            return rejectDay();
        }
        // SET FLG-DAY-ISVALID TO TRUE
        Cobol.moveFigurative(Figurative.LOW_VALUES, f70_WS_EDIT_DAY, CS);
        return 93;
    }

    /** Flags the day as not OK, sets the range message if none is set yet, and goes to EDIT-DAY-EXIT. */
    private int rejectDay() {
        // SET INPUT-ERROR TO TRUE
        Cobol.move("1", f89_WS_INPUT_FLAG, CS);
        // SET FLG-DAY-NOT-OK TO TRUE
        Cobol.move("0", f70_WS_EDIT_DAY, CS);
        // IF WS-RETURN-MSG-OFF
        if (isDayReturnMsgOff()) {
            // STRING FUNCTION TRIM(WS-EDIT-VARIABLE-NAME) ':day must be a number between 1 and 31.' DELIMITED BY SIZE INTO WS-RETURN-MSG
            Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size(Funcs.trim(Cobol.text(f8_WS_EDIT_VARIABLE_NAME, CS)), CS), Cobol.StringPart.size(":day must be a number between 1 and 31.", CS));
        }
        // GO TO EDIT-DAY-EXIT
        return GOTO | 93;
    }

    private boolean isDayReturnMsgOff() {
        return Cobol.compareFigurative(f212_WS_RETURN_MSG, Figurative.SPACES, CS) == 0;
    }

