    /**
     * EDIT-DAY-MONTH-YEAR.
     * Validates the day against the month: no day 31 in a 30-day month, no
     * day 30 in February, and day 29 in February only in a leap year. On an
     * error it flags the date and goes to EDIT-DATE-CCYYMMDD-EXIT; otherwise
     * it falls through only if the date flags are still all valid.
     */
    private int p94() {
        // IF NOT WS-31-DAY-MONTH AND WS-DAY-31
        if (!p94Is31DayMonth() && Cobol.compare(f60_WS_EDIT_DATE_DD_N, D31, CS) == 0) {
            p94FlagDateError(false, ":Cannot have 31 days in this month.");
            return GOTO | 98;
        }
        // IF WS-FEBRUARY AND WS-DAY-30
        if (Cobol.compare(f58_WS_EDIT_DATE_MM_N, D2, CS) == 0 && Cobol.compare(f60_WS_EDIT_DATE_DD_N, D30, CS) == 0) {
            p94FlagDateError(false, ":Cannot have 30 days in this month.");
            return GOTO | 98;
        }
        // IF WS-FEBRUARY AND WS-DAY-29
        if (Cobol.compare(f58_WS_EDIT_DATE_MM_N, D2, CS) == 0 && Cobol.compare(f60_WS_EDIT_DATE_DD_N, D29, CS) == 0) {
            // century years must divide by 400, others by 4
            if (Cobol.num(f55_WS_EDIT_DATE_YY_N, CS).compareTo(D0) == 0) {
                Cobol.move(D400, f46_WS_DIV_BY, CS);
            } else {
                Cobol.move(D4, f46_WS_DIV_BY, CS);
            }
            // DIVIDE WS-EDIT-DATE-CCYY-N BY WS-DIV-BY GIVING WS-DIVIDEND REMAINDER WS-REMAINDER
            BigDecimal v29 = Cobol.divide(Cobol.num(f56_WS_EDIT_DATE_CCYY_N, CS), Cobol.num(f46_WS_DIV_BY, CS));
            Cobol.store(f47_WS_DIVIDEND, v29, false, CS);
            Cobol.store(f48_WS_REMAINDER, Cobol.num(f56_WS_EDIT_DATE_CCYY_N, CS).subtract(Cobol.num(f47_WS_DIVIDEND, CS).multiply(Cobol.num(f46_WS_DIV_BY, CS))), false, CS);
            // IF WS-REMAINDER = ZEROES CONTINUE, ELSE not a leap year
            if (Cobol.num(f48_WS_REMAINDER, CS).compareTo(BigDecimal.ZERO) != 0) {
                p94FlagDateError(true, ":Not a leap year.Cannot have 29 days in this month.");
                return GOTO | 98;
            }
        }
        // IF WS-EDIT-DATE-IS-VALID
        if (Cobol.compareFigurative(f67_WS_EDIT_DATE_FLGS, Figurative.LOW_VALUES, CS) != 0) {
            return GOTO | 98;
        }
        return 95;
    }

    /** WS-31-DAY-MONTH: month is 1, 3, 5, 7, 8, 10 or 12. */
    private boolean p94Is31DayMonth() {
        return Cobol.compare(f58_WS_EDIT_DATE_MM_N, D1, CS) == 0
                || Cobol.compare(f58_WS_EDIT_DATE_MM_N, D3, CS) == 0
                || Cobol.compare(f58_WS_EDIT_DATE_MM_N, D5, CS) == 0
                || Cobol.compare(f58_WS_EDIT_DATE_MM_N, D7, CS) == 0
                || Cobol.compare(f58_WS_EDIT_DATE_MM_N, D8, CS) == 0
                || Cobol.compare(f58_WS_EDIT_DATE_MM_N, D10, CS) == 0
                || Cobol.compare(f58_WS_EDIT_DATE_MM_N, D12, CS) == 0;
    }

    /** Sets input-error and the not-OK flags, and fills WS-RETURN-MSG if it is still empty. */
    private void p94FlagDateError(boolean yearNotOk, String message) {
        // SET INPUT-ERROR TO TRUE
        Cobol.move("1", f89_WS_INPUT_FLAG, CS);
        // SET FLG-DAY-NOT-OK TO TRUE
        Cobol.move("0", f70_WS_EDIT_DAY, CS);
        // SET FLG-MONTH-NOT-OK TO TRUE
        Cobol.move("0", f69_WS_EDIT_MONTH, CS);
        if (yearNotOk) {
            // SET FLG-YEAR-NOT-OK TO TRUE
            Cobol.move("0", f68_WS_EDIT_YEAR_FLG, CS);
        }
        // IF WS-RETURN-MSG-OFF
        if (Cobol.compareFigurative(f212_WS_RETURN_MSG, Figurative.SPACES, CS) == 0) {
            // STRING FUNCTION TRIM(WS-EDIT-VARIABLE-NAME) message DELIMITED BY SIZE INTO WS-RETURN-MSG
            Cobol.string(f212_WS_RETURN_MSG, null, CS, Cobol.StringPart.size(Funcs.trim(Cobol.text(f8_WS_EDIT_VARIABLE_NAME, CS)), CS), Cobol.StringPart.size(message, CS));
        }
    }

